-- Mensaje 102 · La visita de trámite, escrita como prueba (Emilio, 20-oct-2026).
-- Solo cambia si el resumen es el de antes. El chequeo final aborta si no quedó.
UPDATE public.reglas SET resumen = $v$Levantar el pedido de siempre y despedirse sin explorar nada. Al que solo toma pedidos lo reemplaza un formulario. LA PRUEBA: ¿el vendedor se fue con el pedido sin haber descubierto algo más y sin haberlo intentado de verdad? Intentarlo es usar al menos una de las herramientas del hueco —mapear qué otras líneas maneja y con quién, preguntar qué le piden que no tenga, o anclar en negocios como el suyo— y, si la respuesta es vaga («de todo un poco», «lo normal»), seguir: con opciones concretas o con otra herramienta. Una sola pregunta al aire y despedirse después de una respuesta vaga es trámite. Si descubrió algo más, o lo intentó así, no es esto.$v$, updated_at = now() WHERE id = 'develop.visita_tramite' AND resumen = $v$Levantar el pedido de siempre y despedirse sin explorar nada. Al que solo toma pedidos lo reemplaza un formulario.$v$;
DO $chk$ BEGIN
  IF (SELECT resumen FROM public.reglas WHERE id = 'develop.visita_tramite') IS DISTINCT FROM $v$Levantar el pedido de siempre y despedirse sin explorar nada. Al que solo toma pedidos lo reemplaza un formulario. LA PRUEBA: ¿el vendedor se fue con el pedido sin haber descubierto algo más y sin haberlo intentado de verdad? Intentarlo es usar al menos una de las herramientas del hueco —mapear qué otras líneas maneja y con quién, preguntar qué le piden que no tenga, o anclar en negocios como el suyo— y, si la respuesta es vaga («de todo un poco», «lo normal»), seguir: con opciones concretas o con otra herramienta. Una sola pregunta al aire y despedirse después de una respuesta vaga es trámite. Si descubrió algo más, o lo intentó así, no es esto.$v$ THEN RAISE EXCEPTION 'la regla develop.visita_tramite no quedó'; END IF;
END $chk$;
